<template>
 <section class="provider-editor">
  <header><RouterLink to="/models" class="icon-btn" aria-label="返回提供商"><UiIcon name="back"/></RouterLink><h1>{{isNew?'添加提供商':'编辑 '+form.name}}</h1><span>ShizukuAgent</span></header>
  <form @submit.prevent="save">
   <label class="field">提供商标识<input v-model="id" :disabled="!isNew" required pattern="[A-Za-z0-9._-]+"/><small>创建后标识保持不变。</small></label>
   <div class="editor-columns"><label class="field">名称<input v-model="form.name" required/></label><label class="field">模型列表地址（可选）<input v-model="form.models_url" placeholder="留空按 Base URL 获取"/></label></div>
   <label class="field">接口格式<UiSelect model-value="openai" label="接口格式" :options="[{value:'openai',label:'OpenAI Compatible'}]"/></label>
   <label class="field">API Key<input v-model="form.api_key" type="password" autocomplete="off" placeholder="留空保留已保存的密钥"/></label>
   <label class="field">Base URL<input v-model="form.base_url" required type="url" placeholder="https://api.example.com/v1"/></label>
   <section class="editor-block"><div class="block-heading"><div><h2>请求头</h2><p>可选 HTTP 请求头，模型发现与调用使用同一配置。</p></div><button class="btn" type="button" @click="headers.push({key:'',value:''})"><UiIcon name="plus"/>添加请求头</button></div><div v-for="(item,index) in headers" :key="index" class="header-row"><input v-model="item.key" placeholder="Header 名称"/><input v-model="item.value" placeholder="值"/><button class="icon-btn" type="button" aria-label="删除请求头" @click="headers.splice(index,1)"><UiIcon name="delete"/></button></div><p v-if="!headers.length" class="muted">暂无自定义请求头</p></section>
   <section class="editor-block"><div class="block-heading"><div><h2>模型配置</h2><p>模型 ID 用于请求路由；显示名称用于聊天列表。保存后更新该提供商的模型组。</p></div><div><button class="btn" type="button" :disabled="busy" @click="openSelection"><UiIcon name="download"/>获取模型列表</button><button class="btn" type="button" @click="form.models.push('')"><UiIcon name="plus"/>手动添加</button></div></div><div class="model-row-heading"><span>模型 ID</span><span>显示名称</span></div><div v-for="(_model,index) in form.models" :key="index" class="header-row"><input v-model="form.models[index]" placeholder="模型 ID" :aria-label="`模型 ID ${index+1}`" required/><input :value="displayNames[form.models[index]] || form.models[index]" @input="displayNames[form.models[index]]=($event.target as HTMLInputElement).value" placeholder="默认使用模型 ID" :aria-label="`显示名称 ${index+1}`"/><button class="icon-btn" type="button" aria-label="删除模型" @click="form.models.splice(index,1)"><UiIcon name="delete"/></button></div><p v-if="!form.models.length">尚未选择模型。获取列表后勾选，或手动添加模型 ID。</p></section>
   <section class="editor-block"><h2>模型用途</h2><p>聊天模型参与对话；辅助模型只通过工具调用，并在执行前请求审批。</p><label v-for="model in form.models.filter(Boolean)" :key="model" class="field">{{displayNames[model] || model}}<UiSelect v-model="modelRoles[model]" :label="`${model} 用途`" :options="[{value:'chat',label:'对话模型'},{value:'images',label:'辅助 · 绘图'},{value:'speech',label:'辅助 · 语音合成'},{value:'search',label:'辅助 · 搜索'},{value:'embeddings',label:'辅助 · 嵌入'}]"/></label></section>
    <ToastNotice :message="error"/>
   <footer><RouterLink class="btn" to="/models">取消</RouterLink><button class="btn save-button" :disabled="busy">{{busy?'处理中…':'保存'}}</button></footer>
  </form>
   <ModelSelectionDialog :visible="selecting" :provider-name="form.name || '当前提供商'" :remote="remoteModels" :local="localModels" :selected="form.models.filter(Boolean)" :loading="discovering" :error="discoveryError" @cancel="selecting=false" @refresh="discover" @apply="applySelection"/>
 </section>
</template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {request,useAppStore} from '../store/app';import UiSelect from '../components/UiSelect.vue';
import ModelSelectionDialog,{type DiscoveredModel} from '../components/ModelSelectionDialog.vue';
import {modelLabel} from '../modelIdentity';
const route=useRoute(),router=useRouter(),store=useAppStore(),isNew=computed(()=>route.params.id==='new'),id=ref(isNew.value?'':String(route.params.id)),busy=ref(false),error=ref(''),selecting=ref(false),headers=ref<{key:string;value:string}[]>([]);
const form=reactive({name:'',base_url:'',api_key:'',models_url:'',models:[] as string[]});
const displayNames=reactive<Record<string,string>>({}),remoteModels=ref<DiscoveredModel[]>([]),discovering=ref(false),discoveryError=ref('');
const modelRoles=reactive<Record<string,string>>({});
watch(()=>form.models.slice(),ids=>{for(const id of ids){if(!id || modelRoles[id])continue;const stored=store.models.find(m=>m.provider===route.params.id && m.model===id);const caps=Array.isArray(stored?.capabilities)?stored.capabilities:[];modelRoles[id]=caps.includes('image')?'images':caps.includes('speech')?'speech':caps.includes('search')?'search':caps.includes('embedding')?'embeddings':'chat';}},{immediate:true});
const localModels=computed(()=>form.models.filter(Boolean).map(id=>({id,name:displayNames[id]||id})));
function payload(){return {...form,model_roles:modelRoles,model_names:Object.fromEntries(form.models.filter(Boolean).map(id=>[id,displayNames[id]||id])),provider_id:isNew.value?'':id.value,request_headers:Object.fromEntries(headers.value.filter(h=>h.key.trim()).map(h=>[h.key.trim(),h.value]))};}
function openSelection(){remoteModels.value=[];discoveryError.value='';selecting.value=true;void discover();}
async function discover(){if(discovering.value)return;discovering.value=true;discoveryError.value='';try{const data=await request<{models:DiscoveredModel[];api_base_url?:string}>('/api/providers/discover',{method:'POST',body:JSON.stringify(payload())});remoteModels.value=data.models;if(!form.models_url&&data.api_base_url)form.base_url=data.api_base_url;}catch(e){discoveryError.value=e instanceof Error?e.message:'读取失败';}finally{discovering.value=false;}}
function applySelection(ids:string[]){for(const id of ids){if(!displayNames[id])displayNames[id]=remoteModels.value.find(m=>m.id===id)?.name||id;}form.models=ids;selecting.value=false;}
async function save(){busy.value=true;error.value='';try{await request(`/api/providers/${encodeURIComponent(id.value)}`,{method:'PUT',body:JSON.stringify(payload())});await store.loadStatus();await router.push('/models');}catch(e){error.value=e instanceof Error?e.message:'保存失败';}finally{busy.value=false;}}
 onMounted(async()=>{try{await store.loadStatus();if(!isNew.value){const p=store.providers[id.value];if(!p)throw new Error('提供商不存在');Object.assign(form,{name:p.name||id.value,base_url:p.base_url||'',models_url:p.models_url||'',api_key:'',models:store.models.filter(m=>m.provider===id.value&&m.enabled!==false).map(m=>String(m.model))});for(const m of store.models.filter(m=>m.provider===id.value))displayNames[String(m.model)]=modelLabel(m);headers.value=Object.entries((p.request_headers||{}) as Record<string,string>).map(([key,value])=>({key,value}));}}catch(e){error.value=e instanceof Error?e.message:'加载失败';}});
</script>
<style scoped>
.model-row-heading{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding-right:36px;color:var(--muted);font-size:11px;margin:12px 0 6px;}
.provider-editor{max-width:none!important;padding:0!important;height:100%;display:flex;flex-direction:column;}header{display:flex;align-items:center;gap:12px;padding:20px 28px;border-bottom:1px solid var(--border);}header h1{font-size:18px!important;margin:0!important;}header span{color:var(--muted);font-size:13px;}form{padding:20px 28px 80px;overflow:auto;flex:1;}.field{margin-bottom:16px;}.field>input{height:40px;box-sizing:border-box;}.field small{color:var(--muted);font-size:12px;}.editor-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px;}.editor-block{border-left:2px solid var(--border);padding:12px 16px;margin:22px 0;}.block-heading{display:flex;justify-content:space-between;gap:16px;margin-bottom:16px;}.block-heading>div:last-child{display:flex;gap:8px;}h2{font-size:14px;}p{font-size:12px;color:var(--muted);}.header-row{display:flex;gap:12px;margin:10px 0;}.header-row input{flex:1;min-width:0;}footer{position:sticky;bottom:-80px;background:var(--bg);border-top:1px solid var(--border);padding:16px 0;display:flex;justify-content:flex-end;gap:10px;}.save-button{background:#ff7914;color:white;border-color:#ff7914;}.model-choice{width:min(700px,90vw);}.choice-tools{display:flex;gap:10px;}.choice-tools input{flex:1;min-width:0;}.choice-list{height:340px;overflow:auto;border:1px solid var(--border);border-radius:12px;}.choice-list label{display:flex;gap:12px;align-items:center;padding:14px;border-bottom:1px solid var(--border);font-size:13px;}.choice-footer{display:flex;justify-content:flex-end;gap:10px;margin-top:20px;}
</style>
